changeSet.sql:
CREATE TABLE resident_tag (
    resident_id uuid NOT NULL REFERENCES resident(roster_id) ON DELETE CASCADE,
    hamlet_id bigint NOT NULL REFERENCES hamlet(id),
    tag varchar(20) NOT NULL CHECK (tag IN ('DANG_VIEN','CB_HUU_TRI','CCB')),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by varchar(255) NOT NULL,
    PRIMARY KEY (resident_id, tag)
);
CREATE INDEX ix_resident_tag_hamlet ON resident_tag (hamlet_id, tag);

DO $$ BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='police_runtime') THEN
                GRANT SELECT,INSERT,DELETE ON resident_tag TO police_runtime;
            END IF;
        END $$;
